1	// Differential runner: compares the reference executable against node /output/test10.mjs
2	// Usage: node /tmp/harness/diff.mjs [--verbose] [--only <substr>]
3	import { spawnSync } from 'node:child_process';
4	import { cases } from './cases.mjs';
5	
6	const REF = '/workspace/dataset/test10_executable';
7	const JS = '/output/test10.mjs';
8	
9	const argv = process.argv.slice(2);
10	const verbose = argv.includes('--verbose');
11	const onlyIdx = argv.indexOf('--only');
12	const only = onlyIdx >= 0 ? argv[onlyIdx + 1] : null;
13	
14	function run(cmd, args, env) {
15	  const r = spawnSync(cmd, args, {
16	    env: { ...process.env, ...(env || {}) },
17	    encoding: 'buffer',
18	    maxBuffer: 64 * 1024 * 1024,
19	  });
20	  return {
21	    code: r.status,
22	    stdout: (r.stdout || Buffer.alloc(0)).toString('utf8'),
23	    stderr: (r.stderr || Buffer.alloc(0)).toString('utf8'),
24	  };
25	}
26	
27	// Node prints its own banner/stack for uncaught errors; normalize only the prog name in
28	// argparse messages if the JS side ever leaks a different prog (it should not).
29	function show(s) {
30	  return JSON.stringify(s);
31	}
32	
33	let pass = 0;
34	const failures = [];
35	for (const c of cases) {
36	  if (only && !c.name.includes(only)) continue;
37	  const env = c.env || {};
38	  const a = run(REF, c.argv, env);
39	  const b = run(process.execPath, [JS, ...c.argv], env);
40	  const same = a.code === b.code && a.stdout === b.stdout && a.stderr === b.stderr;
41	  if (same) {
42	    pass++;
43	    if (verbose) console.log(`PASS ${c.name}`);
44	  } else {
45	    failures.push({ c, a, b });
46	    console.log(`FAIL ${c.name}  argv=${JSON.stringify(c.argv)} env=${JSON.stringify(env)}`);
47	    if (a.code !== b.code) console.log(`  code: ref=${a.code} js=${b.code}`);
48	    if (a.stdout !== b.stdout) {
49	      console.log(`  stdout ref=${show(a.stdout)}`);
50	      console.log(`         js =${show(b.stdout)}`);
51	    }
52	    if (a.stderr !== b.stderr) {
53	      console.log(`  stderr ref=${show(a.stderr)}`);
54	      console.log(`         js =${show(b.stderr)}`);
55	    }
56	  }
57	}
58	console.log(`\n${pass} passed, ${failures.length} failed, ${pass + failures.length} total`);
59	process.exit(failures.length ? 1 : 0);
