3	// their default options).
4	//
5	// Mirrors CPython 3.11/3.12 Lib/textwrap.py:
6	//   expand_tabs=True, replace_whitespace=True, drop_whitespace=True,
7	//   break_long_words=True, break_on_hyphens=True, initial_indent='',
8	//   subsequent_indent='', fix_sentence_endings=False, max_lines=None.
9	//
10	// No external dependencies (ESM only).
11	
12	// Python: _whitespace = '\t\n\x0b\x0c\r '
13	const WHITESPACE = '\t\n\v\f\r ';
14	
15	// Character classes used to rebuild Python's `wordsep_re`.
16	const WS_CLASS = '[\\t\\n\\x0b\\x0c\\r ]'; // re.escape(_whitespace) equivalent
17	const NWS_CLASS = '[^\\t\\n\\x0b\\x0c\\r ]';
18	const WP_CLASS = '[\\w!"\'&.,?]'; // word_punct
19	const LT_CLASS = '[^\\d\\W]'; // letter
