21	// Python's textwrap.TextWrapper.wordsep_re (re.VERBOSE), one capturing group
22	// spanning the whole pattern.  `\Z` is translated to `$` (no multiline flag).
23	const WORDSEP_SOURCE =
24	  '(' +
25	  WS_CLASS + '+' +
26	  '|(?<=' + WP_CLASS + ')-{2,}(?=\\w)' +
27	  '|' + NWS_CLASS + '+?(?:' +
28	  '-(?:(?<=' + LT_CLASS + '{2}-)|(?<=' + LT_CLASS + '-' + LT_CLASS + '-))' +
29	  '(?=' + LT_CLASS + '-?' + LT_CLASS + ')' +
30	  '|(?=' + WS_CLASS + '|$)' +
31	  '|(?<=' + WP_CLASS + ')(?=-{2,}\\w)' +
32	  '))';
33	
34	const WORDSEP_RE = new RegExp(WORDSEP_SOURCE, 'g');
35	const WORDSEP_SIMPLE_RE = new RegExp('(' + WS_CLASS + '+)', 'g');
