37	// str.expandtabs(tabsize) -- column resets on '\n' and '\r'.
38	function expandTabs(text, tabsize = 8) {
39	  if (text.indexOf('\t') === -1) return text;
40	  let out = '';
41	  let col = 0;
42	  for (const ch of text) {
43	    if (ch === '\t') {
44	      if (tabsize > 0) {
45	        const pad = tabsize - (col % tabsize);
46	        out += ' '.repeat(pad);
47	        col += pad;
48	      }
49	    } else {
50	      out += ch;
51	      if (ch === '\n' || ch === '\r') col = 0;
52	      else col += 1;
53	    }
54	  }
55	  return out;
56	}
